from watcher_runtime import harness
from watcher_runtime.adapters import web_diff

URL = "https://service.berlin.de/dienstleistung/120686/"

try:
    page = web_diff.fetch(URL, None)
except Exception as exc:
    harness.fail("I couldn't read the appointment page just now.")
else:
    state = harness.load_state()
    previous_hash = state.get("hash")
    harness.save_state({"hash": page["content_hash"]})
    if previous_hash is not None and previous_hash != page["content_hash"]:
        harness.emit(
            "act_now",
            "The appointment page has changed. Check it now.",
            "service.berlin.de",
            {"excerpt": page["excerpt"]},
            next_check_s=300
        )
    else:
        harness.emit(
            "ok",
            "No change on the appointment page yet.",
            "service.berlin.de",
            next_check_s=300
        )
